def find_bad_sequence_fixed(C, steps=100):
    eps = 0.00001
    c = [0] * (steps + 1)
    c[1] = C - eps
    R = [0] * (steps + 1)
    R[1] = c[1]
    for k in range(2, steps + 1):
        c[k] = R[k-1]/2 + eps
        if c[k] >= C:
            c[k] = C - eps
        R[k] = 2 * c[k]
        if R[k] > 1:
            return c[:k+1], R[:k+1]
    return None, None

