def find_bad_sequence_v3(C, steps=200):
    eps = 0.000001
    c = [0] * (steps + 1)
    c[1] = C - eps
    R = [0] * (steps + 1)
    R[1] = c[1]
    for k in range(2, steps + 1):
        c[k] = R[k-1]/2 + eps
        if c[k] >= C:
            c[k] = C - eps
        # The range R_k is the range after step k.
        # If we are at the edge, R_k = 2 * c_k.
        # But we can choose c_k to be anything.
        # Wait, if we want to force the range to grow, we want c_k > R_{k-1}/2.
        # If c_k > R_{k-1}/2, the range becomes 2*c_k.
        # Let's try this.
        R[k] = 2 * c[k]
        if R[k] > 1:
            return c[:k+1], R[:k+1]
    return None, None

