def get_next_A(A, c):
    next_A = []
    for a, b in A:
        if a < 1 - c:
            new_a = a + c
            new_b = min(b, 1 - c) + c
            if new_a < new_b:
                next_A.append((new_a, new_b))
        if b > c:
            new_a = max(a, c) - c
            new_b = b - c
            if new_a < new_b:
                next_A.append((new_a, new_b))
    if not next_A:
        return []
    next_A.sort()
    merged = []
    curr_a, curr_b = next_A[0]
    for i in range(1, len(next_A)):
        a, b = next_A[i]
        if a < curr_b:
            curr_b = max(curr_b, b)
        else:
            merged.append((curr_a, curr_b))
            curr_a, curr_b = a, b
    merged.append((curr_a, curr_b))
    return merged

def find_c_min_for_empty_A(max_c, steps=50):
    A = [(0, 1)]
    c_list = []
    for _ in range(steps):
        best_c = -1
        min_measure = float('inf')
        for c in [i/1000 for i in range(1, int(max_c*1000))]:
            next_A = get_next_A(A, c)
            measure = sum(b - a for a, b in next_A)
            if measure < min_measure:
                min_measure = measure
                best_c = c
        if best_c == -1:
            break
        A = get_next_A(A, best_c)
        c_list.append(best_c)
        if not A:
            return c_list
    return None

