def get_next_S(S, c, C):
    # S is a list of (a, b) representing intervals (a, b)
    # S_prev = {d \in (0, 1) \mid (d > c and d-c \in S) or (d < 1-c and d+c \in S)}
    # d-c \in S means d \in S + c
    # d+c \in S means d \in S - c

    # S + c \pmod 1
    S_plus = []
    for a, b in S:
        na, nb = (a + c) % 1, (b + c) % 1
        if na < nb:
            S_plus.append((na, nb))
        else:
            S_plus.append((na, 1))
            S_plus.append((0, nb))

    # S - c \pmod 1
    S_minus = []
    for a, b in S:
        na, nb = (a - c) % 1, (b - c) % 1
        if na < nb:
            S_minus.append((na, nb))
        else:
            S_minus.append((na, 1))
            S_minus.append((0, nb))

    # Union of S_plus and S_minus
    union_S = sorted(S_plus + S_minus)
    merged_S = []
    if union_S:
        curr_a, curr_b = union_S[0]
        for i in range(1, len(union_S)):
            next_a, next_b = union_S[i]
            if next_a < curr_b:
                curr_b = max(curr_b, next_b)
            else:
                merged_S.append((curr_a, curr_b))
                curr_a, curr_b = next_a, next_b
        merged_S.append((curr_a, curr_b))

    # Now we need d > c and d < 1-c
    # S_prev = {d \in merged_S \mid d > c} \cup {d \in merged_S \mid d < 1-c}
    # Wait, the condition is (d > c AND d-c \in S) OR (d < 1-c AND d+c \in S)
    # Let S_plus_valid = {d \in S_plus \mid d > c}
    # Let S_minus_valid = {d \in S_minus \mid d < 1-c}
    # S_prev = S_plus_valid \cup S_minus_valid

    S_plus_valid = []
    for a, b in S_plus:
        ia, ib = max(a, c), b
        if ia < ib:
            S_plus_valid.append((ia, ib))

    S_minus_valid = []
    for a, b in S_minus:
        ia, ib = a, min(b, 1-c)
        if ia < ib:
            S_minus_valid.append((ia, ib))

    union_S = sorted(S_plus_valid + S_minus_valid)
    res = []
    if union_S:
        curr_a, curr_b = union_S[0]
        for i in range(1, len(union_S)):
            next_a, next_b = union_S[i]
            if next_a < curr_b:
                curr_b = max(curr_b, next_b)
            else:
                res.append((curr_a, curr_b))
                curr_a, curr_b = next_a, next_b
        res.append((curr_a, curr_b))
    return res

